// Extract all audio_base64 values
const matches = [...rawResponse.matchAll(/"audio_base64"\s*:\s*"([^"]+)"/g)];

if (matches.length === 0) {
  console.log("No audio_base64 found");
  process.exit(1);
}

// Convert each base64 → Buffer
const buffers = matches.map(match => Buffer.from(match[1], "base64"));

// Combine all buffers into one
const combinedBuffer = Buffer.concat(buffers);

// Save combined file
fs.writeFileSync("combined_audio.mp3", combinedBuffer);

console.log(`Combined ${matches.length} audio chunks into combined_audio.mp3`);